import numpy as np, warnings, sys
warnings.filterwarnings("ignore")
from matchms import Spectrum
from matchms.similarity import FlashSimilarity

def make(seed,n,close=False):
    r=np.random.default_rng(seed)
    mz=np.sort(np.round(r.uniform(5,400,size=n),4))
    if close:
        # inject clusters
        for _ in range(n//4):
            idx=int(r.integers(0,n))
            mz[idx]=mz[min(idx+1,n-1)]+r.uniform(0,0.02)
        mz=np.sort(mz)
    ints=np.round(r.uniform(0.05,1000,size=n),6)
    return Spectrum(mz=mz,intensities=ints,metadata={"precursor_mz":float(mz[-1]+2.0)})

bad=0
for seed in range(30):
    refs=[make(1000+seed*3,15,True) for _ in range(5)]
    qs=[make(2000+seed*3,12,True) for _ in range(6)]
    for tol in [0.01,0.1]:
        sim=FlashSimilarity(tolerance=tol,use_ppm=False,remove_precursor=False,noise_cutoff=0.0,normalize_to_half=True,merge_within=0.0,dtype=np.float64)
        M=np.asarray(sim.matrix(refs,qs,array_type="numpy",n_jobs=0),dtype=float)
        if not np.isfinite(M).all() or (M.min()<-1e-8) or (M.max()>1+1e-6):
            print('BAD bounds',seed,tol,M.min(),M.max()); bad+=1
        # pair consistency for a few
        for i in range(3):
            for j in range(4):
                p=float(np.asarray(sim.pair(refs[i],qs[j])).ravel()[0])
                if abs(p-M[i,j])>1e-12:
                    print('BAD pair',seed,tol,i,j,p,M[i,j]); bad+=1
print('bad count',bad)
